DROP VIEW IF EXISTS model_room;
CREATE VIEW model_room AS SELECT s.guid AS model_room_uu, s.guid, s.type, s.name, s.parent_guid, s.object_type, s.predefined_type, s.center_x, s.center_y, s.center_z, s.size_x, s.size_y, s.size_z, s.room_guid, s.elevation, (SELECT p.name FROM spatial_structure p WHERE p.guid = s.parent_guid) AS storey FROM spatial_structure s WHERE s.type = 'IfcSpace';
